<script setup>
import { inject, ref, watch } from 'vue';
import { api, request } from '../../api';
import { t } from '../../i18n';
const props = defineProps({ active: Boolean });
const { perform } = inject('settings');
const info = ref({ skills: [], roots: [] }), status = ref(''), newName = ref(''), importPath = ref(''), editor = ref(null), file = ref(null), preview = ref(''), zip = ref(null);
watch(() => props.active, active => { if (active) perform(load); }, { immediate: true });
async function load() { info.value = await api('/api/skills'); }
async function toggle(skill, enabled) { info.value = await api(`/api/skills/${encodeURIComponent(skill.name)}/toggle`, { enabled }); }
async function fork(skill) { info.value = await api(`/api/skills/${encodeURIComponent(skill.name)}/fork`, {}); status.value = t('Copied into your workspace — your version now wins.'); }
async function remove(skill) { info.value = await api(`/api/skills/${encodeURIComponent(skill.name)}`, undefined, 'DELETE'); editor.value = null; }
async function openEditor(name) { const data = await api(`/api/skills/${encodeURIComponent(name)}`); editor.value = { ...data, raw: data.raw || '' }; preview.value = ''; }
async function openFile(path) { if (!path) { preview.value = ''; return; } const result = await api(`/api/skills/${encodeURIComponent(editor.value.name)}/file?path=${encodeURIComponent(path)}`); preview.value = result.text || result.error || ''; }
async function save() { const result = await api(`/api/skills/${encodeURIComponent(editor.value.name)}`, { raw: editor.value.raw }, 'PUT'); info.value = result; status.value = t('Saved to {p}', { p: result.path }); }
async function create() { if (!newName.value.trim()) return; const result = await api('/api/skills', { name: newName.value.trim() }); info.value = result; newName.value = ''; await openEditor(result.name); }
async function importFolder() { if (!importPath.value.trim()) return; info.value = await api('/api/skills/import', { path: importPath.value.trim() }); importPath.value = ''; status.value = t('Installed “{n}”.', { n: info.value.name }); }
async function importZip(event) { const selected = event.target.files[0]; event.target.value = ''; if (!selected) return; const response = await request('/api/skills/import', { method: 'POST', headers: { 'Content-Type': 'application/zip' }, body: selected }); info.value = await response.json(); status.value = t('Installed “{n}”.', { n: info.value.name }); }
</script>
<template>
  <div id="paneSkills" class="set-pane" :class="{ hidden: !active }"><div class="modal-sub">{{ t('Skills') }}</div><div id="skillRoots" class="skill-roots"><span v-for="root in info.roots" :key="root.path" class="skill-root" :class="{ missing: !root.exists }"><b>{{ root.source }}</b> <code>{{ root.path }}</code></span></div><label class="mem-toggle"><input id="skillAuto" type="checkbox" :checked="info.auto" @change="perform(async () => { info = await api('/api/skills/auto', { enabled: $event.target.checked }); })" />{{ t('Auto-load the best-matching skill for each task') }}</label><div id="skillList" class="skill-list"><div v-for="skill in info.skills" :key="skill.name" class="skill-row"><input type="checkbox" :checked="skill.enabled" @change="perform(() => toggle(skill, $event.target.checked))" /><span class="skill-main"><span class="skill-name">{{ skill.name }}</span><span class="skill-desc">{{ skill.description || 'no description' }}</span></span><span class="skill-tags"><span class="skill-tag">{{ skill.source }}</span></span><button class="mini-btn sk-edit" @click="perform(() => openEditor(skill.name))">{{ t(skill.source === 'user' ? 'Edit' : 'View') }}</button><a class="mini-btn" :href="`/api/skills/${encodeURIComponent(skill.name)}/export`" download>{{ t('Export') }}</a><button v-if="skill.source === 'user'" class="mini-btn danger sk-del" @click="perform(() => remove(skill))">{{ t('Delete') }}</button><button v-else class="mini-btn sk-fork" @click="perform(() => fork(skill))">{{ t('Fork') }}</button></div></div><div class="skill-foot"><span id="skillStatus" class="tf-status">{{ status }}</span><span class="ca-spacer"></span><input id="skillNewName" v-model="newName" class="text-input" placeholder="new-skill-name" /><button id="skillNew" class="mini-btn primary" @click="perform(create)">{{ t('New') }}</button><button id="skillImportZip" class="mini-btn" @click="zip.click()">{{ t('Import .zip') }}</button><input id="skillZipFile" ref="zip" type="file" accept=".zip" hidden @change="perform(() => importZip($event))" /></div><div class="skill-foot"><input id="skillImportPath" v-model="importPath" class="text-input" placeholder="…or a folder path under the workspace" /><button id="skillImportGo" class="mini-btn" @click="perform(importFolder)">{{ t('Import folder') }}</button></div><div v-if="editor" id="skillEditor" class="skill-editor"><div class="se-head"><span id="seTitle" class="se-title">{{ editor.name }}</span><span class="ca-spacer"></span><button id="seClose" class="mini-btn" @click="editor = null">{{ t('Close') }}</button><button id="seSave" class="mini-btn primary" @click="perform(save)">{{ t('Save') }}</button></div><div id="seNote" class="se-note">{{ editor.path }}</div><div id="seFiles" class="se-files"><a class="sef" href="#" @click.prevent="preview = ''">SKILL.md</a><a v-for="entry in (editor.files || []).filter(f => f.readable).slice(0, 40)" :key="entry.path" class="sef" href="#" @click.prevent="perform(() => openFile(entry.path))">{{ entry.path }}</a></div><pre v-if="preview" id="sePreview" class="se-preview">{{ preview }}</pre><textarea v-else id="seText" v-model="editor.raw" class="mem-text" spellcheck="false"></textarea></div></div>
</template>
